-- Runs under an OLD version of empirical-science: builds a small base whose saved state the new
-- version must then load. Uses only what may exist (pcall around version-specific calls).
-- A fingerprint of the hidden world (every Tier 1 response on gears and circuits, family chemistry): written by the old
-- version and by the new one after loading; upgrade_test.sh compares them (a world must never be
-- regenerated by an upgrade).
local function truth_fingerprint()
  local ok, t = pcall(remote.call, "empirical-science", "truth")
  if not (ok and t and t.targets) then return nil end
  local lines = {}
  for _, key in ipairs({"gear", "circuit"}) do
    for _, a in ipairs({"coal", "wood", "stone", "stone-brick", "copper-cable"}) do
      local r = t.targets[key] and t.targets[key][a]
      if r then table.insert(lines, string.format("%s %s %s %.9f %.9f %.9f", key, a, tostring(r.kind), r.peak or 0, r.opt or 0, r.score or 0)) end
    end
  end
  -- Drawn after the targets in a fresh world: a regeneration shows here first (family chemistry).
  local fams = {}
  for fam in pairs(t.chem or {}) do table.insert(fams, fam) end
  table.sort(fams)
  for _, fam in ipairs(fams) do table.insert(lines, string.format("chem %s %.9f", fam, t.chem[fam])) end
  if t.responsiveness and t.responsiveness.gear then
    table.insert(lines, string.format("responsiveness gear %.9f", t.responsiveness.gear))
  end
  return table.concat(lines, "\n") .. "\n"
end

script.on_init(function()
  -- This mod depends on empirical-science, whose on_init (the world's truth) has run already.
  local fp = truth_fingerprint()
  if fp then helpers.write_file("es-truth-before.txt", fp) end
  local s = game.surfaces.nauvis
  s.request_to_generate_chunks({0, 0}, 3); s.force_generate_chunk_requests()
  for _, e in pairs(s.find_entities_filtered{area = {{-40, -40}, {40, 40}}}) do e.destroy() end
  local tiles = {}
  for x = -40, 39 do for y = -40, 39 do table.insert(tiles, {name = "lab-dark-1", position = {x, y}}) end end
  s.set_tiles(tiles)
  for _, t in pairs(game.forces.player.technologies) do t.researched = true end
  local function place(name, x, y)
    if not prototypes.entity[name] then return nil end
    return s.create_entity{name = name, position = {x, y}, force = "player", raise_built = true}
  end
  place("electric-energy-interface", -10, 10)
  for x = -10, 30, 6 do place("substation", x, 6) end
  local station = place("es-analysis-station", 0, 20)
  for i, r in ipairs({"es-trial-gear-control", "es-trial-gear-stone-5", "es-trial-gear-coal-3"}) do
    local b = place("es-test-bench", (i - 1) * 5, 0)
    if b and prototypes.recipe[r] then
      b.set_recipe(r)
      b.get_inventory(defines.inventory.crafter_input).insert{name = "iron-plate", count = 100}
    end
  end
  -- Samples already in the station (their tags in this version's format) and packs.
  if station then
    local inv = station.get_inventory(defines.inventory.chest)
    -- (0.72 made samples one item per pack; es-sample stays a legacy item there, which stations refuse.)
    local sample = prototypes.item["es-sample-automation-science-pack"] and "es-sample-automation-science-pack" or "es-sample"
    for i = 1, 6 do
      inv.insert{name = sample, count = 1, tags = {target = "gear", additive = i % 2 == 0 and "stone" or "",
        dose = i % 2 == 0 and 5 or 0, y = 10 + i, pack = "automation-science-pack"}}
    end
    inv.insert{name = "automation-science-pack", count = 50}
    log("es-upgrade-setup: station holds " .. inv.get_item_count(sample) .. " " .. sample .. ", " .. inv.get_item_count("automation-science-pack") .. " packs")
  end
  -- Residues by family (0.39): stone brick's residue and catalyst, where this version has them, in a
  -- chest; the copper plates say which (1: residue, 2: catalyst, 3: both), for es-upgrade-check.
  local rc = place("steel-chest", -20.5, -20.5)
  if rc then
    local marker = 0
    for bit, name in pairs({[1] = "es-spent-stone-brick", [2] = "es-refined-stone-brick"}) do
      if prototypes.item[name] then rc.insert{name = name, count = 20}; marker = marker + bit end
    end
    if marker > 0 then rc.insert{name = "copper-plate", count = marker} end
  end
  -- An exhaust hopper holding residues (0.33-0.64), where this version has one: 0.65 makes it a steel chest.
  local ex = place("es-exhaust-hopper", -24.5, -20.5)
  if ex and ex.valid then  -- (0.65 on retires one as it is built)
    ex.insert{name = "es-spent-coal", count = 17}
    place("wooden-chest", -24.5, -23.5)  -- marker for es-upgrade-check: a live exhaust was built
  end
  -- A version before 0.70 (its worlds have none of 0.70's laws): a marker for es-upgrade-check.
  local major, minor = (script.active_mods["empirical-science"] or "0.0.0"):match("^(%d+)%.(%d+)")
  if tonumber(major) == 0 and tonumber(minor) < 70 then place("small-lamp", -40.5, -20.5) end
  -- A hopper (its bar kept slots for spent, 0.14-0.64): 0.65 drops the bar.
  place("es-hopper", -28.5, -20.5)
  -- Hoppers with a fluid port overlaid (before 0.71): one holding only lubricant, one coal and lubricant.
  -- 0.71 makes the first a fluid hopper holding the lubricant; the second keeps its coal and loses its port.
  if prototypes.entity["es-hopper-fluid-port"] then
    local function with_lubricant(x)
      local h = place("es-hopper", x, -20.5)
      local port = h and s.find_entities_filtered{name = "es-hopper-fluid-port", position = h.position, radius = 0.5}[1]
      if port then port.insert_fluid{name = "lubricant", amount = 100, temperature = 25} end
      return h
    end
    with_lubricant(-32.5)
    local mixed = with_lubricant(-36.5)
    if mixed then mixed.insert{name = "coal", count = 5} end
    place("iron-chest", -32.5, -23.5)  -- marker for es-upgrade-check: ported hoppers were built
  end
  place("es-advanced-bench", 12.5, 11.5)
  local plant = place("es-formulation-plant", 20.5, 11.5)
  -- Formulations as they were before the catalogue (0.7-0.10): a composition adopted for circuits, a
  -- plant on that target, and an assembler running the old formulated recipe on old stock.
  if plant and remote.interfaces["empirical-science"] and remote.interfaces["empirical-science"].form_set_target then
    pcall(remote.call, "empirical-science", "adopt_mix", "player", "circuit", {sulfur = 3, coal = 2})
    pcall(remote.call, "empirical-science", "form_set_target", plant.unit_number, "circuit")
    local fa = place("assembling-machine-2", 30, 12)
    fa.set_recipe("es-formulated-circuit")
    local fin = fa.get_inventory(defines.inventory.crafter_input)
    fin.insert{name = "es-formulation-circuit", count = 20}
    fin.insert{name = "iron-plate", count = 200}
    fin.insert{name = "copper-cable", count = 400}
  end
  local asm = place("assembling-machine-2", 30, 0)
  pcall(remote.call, "empirical-science", "adopt", "player", "gear", "stone", 5)
  if asm and prototypes.recipe["es-catalysed-gear-stone-5"] then asm.set_recipe("es-catalysed-gear-stone-5") end
end
)
